 public MainWindow(RadarRuntime runtime){InitializeComponent();_runtime=runtime;_expanded=runtime.Settings.Expanded;ExpandButton.Click+=(_,_)=>SetExpanded(!_expanded);ExpandButton.ToolTip="展开或收起";ExpandButton.Background=Brushes.Transparent;ExpandButton.Foreground=Brushes.White;ExpandButton.BorderThickness=new Thickness(0);ExpandButton.FontSize=22;
