 public void SetExpanded(bool value){_expanded=value;_hover.PresentationChanged(value,IsMouseOver);_runtime.UpdateSettings(s=>s.Expanded=value);Render();}
 void OnChanged(){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(OnChanged);return;}Render();}
 void OnNotice(NoticeRecord n){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(()=>OnNotice(n));return;}ShowNotice(n);}
 public void ShowNotice(NoticeRecord n){var first=_notices.Current?.Id!=n.Id;if(_notices.Show(n)&&first&&_runtime.Settings.Sound)ReminderSound.TryPlay();RenderNotice();}
 void RenderNotice(){if(_notices.Current==null){_reminder?.Hide();return;}if(_reminder==null){_reminder=new ReminderWindow();_reminder.Acknowledged+=()=>{if(_notices.Current!=null)_runtime.AcknowledgeNotice(_notices.Current.Id);_notices.Close();RenderNotice();};_reminder.AcknowledgedAll+=()=>{foreach(var n in _runtime.Notices)_runtime.AcknowledgeNotice(n.Id);_notices.CloseAll();RenderNotice();};_reminder.OpenRequested+=async()=>{var row=CurrentNoticeRow();if(row!=null){var r=await _runtime.OpenAsync(row);_reminder.SetStatus(r.Message);if(r.OpenedConversation){_notices.Close();RenderNotice();}}};_reminder.RecoverRequested+=()=>{var row=CurrentNoticeRow();if(row!=null)_runtime.ManualResume(row);};}_reminder.Render(_notices.Current,_notices.PendingCount,_runtime.Settings.Popup,_platform?.IdleSeconds??100,_right,Top,Width,Height);}
