 ExpandedHost.Children.Clear();ExpandedHost.Visibility=_expanded?Visibility.Visible:Visibility.Collapsed;CompactHost.Visibility=_expanded?Visibility.Collapsed:Visibility.Visible;ExpandButton.Content=_expanded?"‹":"›";Width=_expanded?238:60;
 if(_expanded){var dock=new DockPanel{LastChildFill=true};var header=new Grid{Height=40,Margin=new Thickness(12,0,32,0)};header.Children.Add(new TextBlock{Text=$"任务雷达  {active}",FontSize=14,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center});header.MouseLeftButtonDown+=(_,e)=>{if(e.ClickCount==2){OpenSettings();return;}_dragging=true;try{DragMove();}finally{_dragging=false;_right=Left+Width;PersistPosition();}};DockPanel.SetDock(header,Dock.Top);dock.Children.Add(header);
 var footer=new StackPanel{Margin=new Thickness(10,3,10,6)};var actions=new StackPanel{Orientation=Orientation.Horizontal};actions.Children.Add(Button(settings.Paused?"继续":"暂停",()=>_runtime.UpdateSettings(s=>s.Paused=!s.Paused)));actions.Children.Add(Button("设置",OpenSettings));actions.Children.Add(Button("•••",()=>Menu().IsOpen=true));footer.Children.Add(actions);footer.Children.Add(new TextBlock{Text=$"{(settings.Mode=="rage"?"狂暴":"协作")} · {(settings.AutoSend?"自动发送":"仅提醒")} · 排队 {_runtime.QueueCount}",FontSize=10,Foreground=Palette.Brush(Palette.Muted),Margin=new Thickness(0,4,0,0)});DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);
 var list=new StackPanel{Margin=new Thickness(8,0,8,0)};var groups=SessionGroups.Build(rows,_runtime.Sessions,settings.RemovedIds,_expandedApps);if(groups.Length==0)list.Children.Add(new TextBlock{Text=settings.Paused?"监控已暂停":"没有可显示的对话\n等待本地会话证据",Margin=new Thickness(8,18,8,18),FontSize=12,Foreground=Palette.Brush(Palette.Muted)});
 foreach(var group in groups){var container=new StackPanel();var row=group.Primary;container.Children.Add(Row(row,group.Rows.Length));if(_expandedApps.Contains(group.Id))foreach(var child in group.Rows.Skip(1))container.Children.Add(Row(child,0));list.Children.Add(container);}
 dock.Children.Add(new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});ExpandedHost.Children.Add(dock);Height=SessionGroups.PanelHeight(SessionGroups.ContentHeight(groups,_expandedApps),false,WorkAreas.Containing(_right,Top,this).Height);
 }else Height=32;var work=WorkAreas.Containing(_right,Top,this);Left=Math.Clamp(_right-Width,work.Left,Math.Max(work.Left,work.Right-Width));Top=Math.Clamp(Top,work.Top,Math.Max(work.Top,work.Bottom-Height));_right=Left+Width;
 CompactHost.MouseLeftButtonDown-=DragCompact;CompactHost.MouseLeftButtonDown+=DragCompact;ContextMenu=Menu();
 var found=_runtime.Fresh&&!settings.Paused?ConflictFinder.Detect(rows):Array.Empty<WorkspaceConflict>();foreach(var c in found)if(_conflicts.Add(c.Fingerprint))ShowNotice(new NoticeRecord("conflict:"+c.Fingerprint,"conflict:"+c.Path,"同目录协作提醒",c.Folder,c.Detail,"conflict",false));if(_runtime.Fresh)_conflicts.IntersectWith(found.Select(c=>c.Fingerprint));}
 Border Row(SessionRecord row,int count){var content=new StackPanel{Margin=new Thickness(8,5,8,5)};var head=new DockPanel();if(count>1){var toggle=Button((_expandedApps.Contains(row.AppId)?"⌃":"⌄")+$" {count}",()=>{if(!_expandedApps.Remove(row.AppId))_expandedApps.Add(row.AppId);Render();});DockPanel.SetDock(toggle,Dock.Right);head.Children.Add(toggle);}head.Children.Add(new TextBlock{Text=row.AppName+(_runtime.Settings.CareIds.Contains(row.Id)?" · 持续关照":""),FontSize=11,Foreground=Palette.Brush(Palette.Muted)});content.Children.Add(head);content.Children.Add(new TextBlock{Text=_runtime.Settings.Labels.GetValueOrDefault(row.Id,SessionText.Primary(row)),FontWeight=FontWeights.SemiBold,FontSize=13,TextTrimming=TextTrimming.CharacterEllipsis});var second=SessionText.Secondary(row);if(second!=null)content.Children.Add(new TextBlock{Text=second,FontSize=10,Foreground=Palette.Brush(Palette.Muted),TextTrimming=TextTrimming.CharacterEllipsis});content.Children.Add(new TextBlock{Text=row.StatusLabel+" · "+SessionText.Elapsed(row,SessionText.Now()),FontSize=10,Foreground=Palette.Brush(Palette.Status(row))});var border=new Border{Child=content,Background=new SolidColorBrush(Color.FromArgb(15,255,255,255)),CornerRadius=new CornerRadius(10),Margin=new Thickness(0,2,0,2),ToolTip=SessionText.Detail(row,SessionText.Now()),Cursor=Cursors.Hand};border.MouseLeftButtonUp+=async(_,_)=>{var result=await _runtime.OpenAsync(row);if(!result.OpenedConversation)Report(result.Message);};var menu=new ContextMenu();Add(menu,"打开原会话",async()=>Report((await _runtime.OpenAsync(row)).Message));Add(menu,"查询输入组件",async()=>{var r=await _runtime.InspectAsync(row);ProductDialog.Show("会话组件查询",r.DiagnosticSummary??RadarRuntime.Explain(r.Code));});Add(menu,"恢复一次 / 请继续",()=>_runtime.ManualResume(row));Add(menu,"监督此会话",()=>_runtime.ToggleSupervision(row));if(row.AppId=="openclaw")Add(menu,_runtime.Settings.CareIds.Contains(row.Id)?"关闭 OpenClaw 持续关照":"开启 OpenClaw 持续关照",()=>_runtime.ToggleCare(row));Add(menu,_runtime.Settings.Pins.Contains(row.Id)?"取消置顶":"置顶",()=>_runtime.UpdateSettings(s=>{if(!s.Pins.Remove(row.Id))s.Pins.Add(row.Id);}));Add(menu,"修改显示名称",()=>{if(ProductDialog.TryAsk("显示名称",_runtime.Settings.Labels.GetValueOrDefault(row.Id,row.DisplayName),out var name))_runtime.UpdateSettings(s=>{if(string.IsNullOrWhiteSpace(name))s.Labels.Remove(row.Id);else s.Labels[row.Id]=name;});});Add(menu,"移除此会话",()=>_runtime.Remove(row));border.ContextMenu=menu;return border;}
 void DragCompact(object sender,MouseButtonEventArgs e){_dragging=true;try{DragMove();}finally{_dragging=false;_right=Left+Width;PersistPosition();}}
 void PersistPosition()=>_runtime.UpdateSettings(s=>{s.X=_right;s.Y=Top;});
 ContextMenu Menu(){var m=new ContextMenu();Add(m,"设置…",OpenSettings);Add(m,"辅助功能自助检查…",()=>{if(_platform!=null)new AccessRepairWindow(()=>_platform.CheckAccessibilityAsync(),()=>ProductDialog.Show("Windows 窗口权限","请解锁桌面；任务雷达与目标应用使用相同权限级运行。" )).Show();});Add(m,"监控诊断…",()=>ProductDialog.Show("监控诊断",_runtime.Diagnostic));Add(m,"恢复移除的会话",_runtime.RestoreRemoved);Add(m,"恢复默认位置",()=>{var a=SystemParameters.WorkArea;_right=a.Right-22;Top=a.Top+22;PersistPosition();Render();});Add(m,"退出",()=>ExitRequested?.Invoke());m.PlacementTarget=this;return m;}
 public void OpenSettings(){if(CurrentSettingsWindow!=null){CurrentSettingsWindow.Activate();return;}var settings=new SettingsWindow(_runtime,_platform);CurrentSettingsWindow=settings;settings.Closed+=(_,_)=>CurrentSettingsWindow=null;settings.Show();}
 public void Report(string message)=>ProductDialog.Show("任务雷达",message);
 public void PrepareForExit(){_exiting=true;_timer.Stop();_runtime.Changed-=OnChanged;_runtime.NoticeRaised-=OnNotice;_reminder?.Close();CurrentSettingsWindow?.CloseWithoutPrompt();Close();}
 internal static Button Button(string title,Action action){var b=new Button{Content=title,Padding=new Thickness(8,4,8,4),Margin=new Thickness(2),FontSize=11};AutomationProperties.SetName(b,title);b.Click+=(_,_)=>action();return b;}
 static void Add(ContextMenu menu,string title,Action action){var item=new MenuItem{Header=title};item.Click+=(_,_)=>action();menu.Items.Add(item);}
